import{_ as o,l as i,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"持久化与路径复制","description":"","frontmatter":{"title":"持久化与路径复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/persistent-path-copy.md","filePath":"cs/persistent-path-copy.md","lastUpdated":1789023840000}'),h={name:"cs/persistent-path-copy.md"};function m(_,a,u,f,S,A){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="持久化与路径复制" tabindex="-1">持久化与路径复制 <a class="header-anchor" href="#持久化与路径复制" aria-label="Permalink to &quot;持久化与路径复制&quot;">​</a></h1><div class="epigraph"><p>更新不覆盖旧节点：复制根到修改点的路径，其余子树指针共享。旧根仍是完整的旧版本。</p><footer>—— 据 Driscoll, Sarnak, Sleator and Tarjan, Making Data Structures Persistent, JCSS 1989；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/t-digest-quantile">上一课</a> 收束近似摘要。<a href="/cs/persistent-segment-tree">可持久化线段树</a> 已在区间树上做过一遍；<a href="/cs/hamt">HAMT</a> 与 <a href="/cs/rope-structure">Rope</a> 也用了共享。本课把方法从特例抽出来：部分持久 / 完全持久 / 函数式，以及路径复制的代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>版本控制、回溯、函数式语义要「改完仍能读旧」。fat node 在节点里存时间线，完全持久强、实现烦。路径复制：树（或 DAG 指针结构）每次更新 \\(\\Theta(h)\\) 新节点。缺口是<strong>一般树结构的版本 = 根指针</strong>，以及何时必须 fat node（有向图入度大、路径不唯一）。</p><p><span class="marginnote">Driscoll et al., <em>JCSS</em>, 1989。Okasaki 强调惰性与摊还在函数式堆/队列上的用法。本课先命令式复制，惰性下一课队列再用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只读操作沿当前根，不写。写入：自叶向上 <code>new</code>，孩子指针指向旧或新。几何树、BST、线段树同一套路。可并堆破坏性 meld 会弄丢旧堆；函数式 meld 复制路径，接<a href="/cs/mergeable-heap">可并堆</a> 合同但表示不同。</p>',8)),(e(),n(c,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%B9%22%5D%20--%3E%20SH%5B%22%E5%85%B1%E4%BA%AB%E5%AD%90%E6%A0%91%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%A0%B9%22%5D%20--%3E%20PATH%5B%22%E5%A4%8D%E5%88%B6%E7%9A%84%20O(h)%20%E8%8A%82%E7%82%B9%22%5D%0A%20%20PATH%20--%3E%20SH%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>空间：\\(m\\) 次更新 \\(O(m h)\\)。不要原地改已共享节点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引用计数或 GC 回收无根可达的版本。多版本并发控制在数据库里同构，本课只钉内存结构。并发写同一逻辑树需 CAS 根或后课无锁，路径复制本身不解决线性化。</p><p>缓存无关布局下一课换的是扫描顺序，与版本正交；但可组合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 DSST 动态树持久化写完。图结构共享比树难。函数式 FIFO 有「倒栈」技巧，下一课专收，避免在这里把队列摊还证完。</p><p>后课默认：树的不可变更新用路径复制。函数式队列用双栈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路径复制：新版本 \\(O(h)\\) 节点，旧根只读。</li><li>共享子树；禁止写共享节点。</li><li>下一课把该方法用在 FIFO 上。</li><li>出处：Driscoll et al., <em>JCSS</em>, 1989；Okasaki。</li></ul>',9))])}const k=o(h,[["render",m]]);export{E as __pageData,k as default};
